import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <vector>
#include <limits>
using namespace cute;
__device__ __forceinline__ void atomicMinFloatDevice(float* addr, float value) {
  int* addr_as_int = reinterpret_cast<int*>(addr);
  int old = *addr_as_int, assumed;
  do {
    float old_f = __int_as_float(old);
    if (old_f <= value) break;
    assumed = old;
    old = atomicCAS(addr_as_int, assumed, __float_as_int(value));
  } while (assumed != old);
}
// Generic reduction: input viewed as (outer, reduce, inner) contiguous tensor,
// output viewed as (outer, inner) contiguous tensor. Min-reduce over the
// middle ("reduce") dimension, split across gridDim.z chunks combined via
// atomic-min to increase block-level parallelism and occupancy on the GPU.
template <typename T>
__global__ void min_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int S0, int S1, int S2, // outer, reduce, inner
    int chunk_size)
{
  constexpr int VEC = 8;
  int inner_base = (blockIdx.x * blockDim.x + threadIdx.x) * VEC;
  if (inner_base >= S2) return;
  int remaining = S2 - inner_base;
  int chunk_start = blockIdx.z * chunk_size;
  if (chunk_start >= S1) return;
  int chunk_end = chunk_start + chunk_size;
  if (chunk_end > S1) chunk_end = S1;
  for (int outer_idx = blockIdx.y; outer_idx < S0; outer_idx += gridDim.y) {
    const int64_t row_off = (int64_t)outer_idx * (int64_t)S1 * (int64_t)S2 + inner_base;
    if (remaining >= VEC) {
      const T* p0 = X + row_off + (int64_t)chunk_start * S2;
      T minv0, minv1, minv2, minv3, minv4, minv5, minv6, minv7;
      bool aligned0 = (((size_t)p0) % 16 == 0);
      if (aligned0) {
        float4 vlo = *reinterpret_cast<const float4*>(p0);
        float4 vhi = *reinterpret_cast<const float4*>(p0 + 4);
        minv0 = vlo.x; minv1 = vlo.y; minv2 = vlo.z; minv3 = vlo.w;
        minv4 = vhi.x; minv5 = vhi.y; minv6 = vhi.z; minv7 = vhi.w;
      } else {
        minv0 = p0[0]; minv1 = p0[1]; minv2 = p0[2]; minv3 = p0[3];
        minv4 = p0[4]; minv5 = p0[5]; minv6 = p0[6]; minv7 = p0[7];
      }
      #pragma unroll 8
      for (int h = chunk_start + 1; h < chunk_end; ++h) {
        const T* p = X + row_off + (int64_t)h * S2;
        bool aligned = (((size_t)p) % 16 == 0);
        if (aligned) {
          float4 vlo = *reinterpret_cast<const float4*>(p);
          float4 vhi = *reinterpret_cast<const float4*>(p + 4);
          minv0 = vlo.x < minv0 ? vlo.x : minv0;
          minv1 = vlo.y < minv1 ? vlo.y : minv1;
          minv2 = vlo.z < minv2 ? vlo.z : minv2;
          minv3 = vlo.w < minv3 ? vlo.w : minv3;
          minv4 = vhi.x < minv4 ? vhi.x : minv4;
          minv5 = vhi.y < minv5 ? vhi.y : minv5;
          minv6 = vhi.z < minv6 ? vhi.z : minv6;
          minv7 = vhi.w < minv7 ? vhi.w : minv7;
        } else {
          T x0 = p[0], x1 = p[1], x2 = p[2], x3 = p[3];
          T x4 = p[4], x5 = p[5], x6 = p[6], x7 = p[7];
          minv0 = x0 < minv0 ? x0 : minv0;
          minv1 = x1 < minv1 ? x1 : minv1;
          minv2 = x2 < minv2 ? x2 : minv2;
          minv3 = x3 < minv3 ? x3 : minv3;
          minv4 = x4 < minv4 ? x4 : minv4;
          minv5 = x5 < minv5 ? x5 : minv5;
          minv6 = x6 < minv6 ? x6 : minv6;
          minv7 = x7 < minv7 ? x7 : minv7;
        }
      }
      T* ybase = Y + (int64_t)outer_idx * S2 + inner_base;
      atomicMinFloatDevice(ybase + 0, minv0);
      atomicMinFloatDevice(ybase + 1, minv1);
      atomicMinFloatDevice(ybase + 2, minv2);
      atomicMinFloatDevice(ybase + 3, minv3);
      atomicMinFloatDevice(ybase + 4, minv4);
      atomicMinFloatDevice(ybase + 5, minv5);
      atomicMinFloatDevice(ybase + 6, minv6);
      atomicMinFloatDevice(ybase + 7, minv7);
    } else {
      for (int k = 0; k < remaining; ++k) {
        const T* p = X + row_off + k + (int64_t)chunk_start * S2;
        T minv = p[0];
        for (int h = chunk_start + 1; h < chunk_end; ++h) {
          T v = X[row_off + k + (int64_t)h * S2];
          minv = v < minv ? v : minv;
        }
        atomicMinFloatDevice(Y + (int64_t)outer_idx * S2 + inner_base + k, minv);
      }
    }
  }
}
__global__ void fill_inf_kernel(float* __restrict__ Y, int64_t n) {
  const float inf = std::numeric_limits<float>::infinity();
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  int64_t vec_n = n / 4;
  float4* Y4 = reinterpret_cast<float4*>(Y);
  float4 finf = make_float4(inf, inf, inf, inf);
  for (int64_t i = idx; i < vec_n; i += stride) {
    Y4[i] = finf;
  }
  int64_t rem_start = vec_n * 4;
  for (int64_t i = rem_start + idx; i < n; i += stride) {
    Y[i] = inf;
  }
}
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  int64_t ndim = x_c.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  int64_t reduce_size = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);
  std::vector<int64_t> out_shape;
  out_shape.reserve(ndim - 1);
  for (int64_t i = 0; i < ndim; ++i) {
    if (i != dim) out_shape.push_back(x_c.size(i));
  }
  TORCH_CHECK(reduce_size > 0, "reduction dimension must have size > 0");
  auto y = torch::empty(out_shape, x_c.options());
  {
    int64_t out_numel = y.numel();
    if (out_numel > 0) {
      const int fill_threads = 256;
      int64_t vec_elems = (out_numel + 3) / 4;
      int64_t fill_blocks = (vec_elems + fill_threads - 1) / fill_threads;
      if (fill_blocks < 1) fill_blocks = 1;
      if (fill_blocks > 65535) fill_blocks = 65535;
      cudaStream_t init_stream = c10::cuda::getCurrentCUDAStream().stream();
      fill_inf_kernel<<<(unsigned)fill_blocks, fill_threads, 0, init_stream>>>(
          y.data_ptr<float>(), out_numel);
    }
  }
  if (outer == 0 || inner == 0) {
    return y;
  }
  const int threads = 256;
  const int VEC = 8;
  dim3 block(threads);
  int64_t cols_per_block = (int64_t)threads * VEC;
  unsigned grid_x = (unsigned)((inner + cols_per_block - 1) / cols_per_block);
  unsigned grid_y = (unsigned)std::min<int64_t>(outer, 65535);
  // Split the reduction dimension across gridDim.z to increase the number of
  // concurrently schedulable blocks (improves occupancy for large reduce
  // dimensions with small outer/inner extents). Partial results are combined
  // with an atomic-min into the output tensor (pre-initialized to +inf).
  int64_t desired_chunks = 256;
  int64_t chunk_size = (reduce_size + desired_chunks - 1) / desired_chunks;
  if (chunk_size < 1) chunk_size = 1;
  unsigned grid_z = (unsigned)((reduce_size + chunk_size - 1) / chunk_size);
  if (grid_z < 1) grid_z = 1;
  dim3 grid(grid_x, grid_y, grid_z);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)reduce_size, (int)inner, (int)chunk_size);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a
    custom CUTE/CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_forward(x, self.dim)

